target=(A[:,:9]==3)
# dimensions (h,w) objs: zero singleton x2;7 2x2;8 3x5;9 2x5;5 3x2;1 1x5;4 2x4;checker 6x4
objs=[('0a',1,1),('0b',1,1),('7',2,2),('8',3,5),('9',2,5),('5',3,2),('1',1,5),('4',2,4),('checker',6,4)]
# each dimensions can rotate, but checker not rotate? allow rotations, pattern transform later
placements=[]
for idx,(name,h,w) in enumerate(objs):
 options={(h,w),(w,h)}
 for hh,ww in options:
  for r in range(20-hh+1):
   for c in range(9-ww+1):
    cells={(rr,cc) for rr in range(r,r+hh) for cc in range(c,c+ww)}
    if all(target[rr,cc] for rr,cc in cells):
     placements.append((idx,name,hh,ww,r,c,cells))
from collections import defaultdict
bycell=defaultdict(list)
for pl in placements:
 for cell in pl[-1]: bycell[cell].append(pl)
print('placements',len(placements))
